<script setup lang="ts">import{onMounted,ref}from'vue';import{Page}from'@vben/common-ui';import{ElMessage}from'element-plus';import{getAccessCodesApi}from'#/api/core/auth';import{getPlatformSMSApi,savePlatformSMSApi}from'#/api/core/platform-sms';const config=ref(''),note=ref(''),loading=ref(false),saving=ref(false),canManage=ref(false);async function load(){loading.value=true;try{const d=await getPlatformSMSApi();config.value=d.config;note.value=d.note}finally{loading.value=false}}async function save(){if(!config.value.trim()){ElMessage.warning('配置不能为空');return}saving.value=true;try{await savePlatformSMSApi(config.value.trim());ElMessage.success('短信 stub 配置已保存')}finally{saving.value=false}}onMounted(async()=>{const [permissions]=await Promise.all([getAccessCodesApi(),load()]);canManage.value=permissions.includes('setting.sms.manage')});</script><template><Page title="短信配置" description="仅维护无密钥短信 stub；真实通道凭据不在后台保存或回显。"><el-card v-loading="loading" shadow="never"><el-alert :title="note" type="warning" :closable="false" class="mb-4"/><el-input v-model="config" :disabled="!canManage" :rows="14" type="textarea" placeholder="仅支持 provider=stub 的 JSON 配置"/><div class="mt-4 flex justify-end"><el-button @click="load">重置</el-button><el-button v-if="canManage" :loading="saving" type="primary" @click="save">保存配置</el-button></div></el-card></Page></template>
